/**
 * sound.ts — the video's audio plan.
 *
 * Like timing.ts this is pure arithmetic: it walks TIMELINE and returns
 *   - SFX cues     (absolute frame, file, optional playbackRate), and
 *   - music envelopes (per-frame volume for each of the three music layers).
 * Nothing here touches the DOM, so every frame is deterministic and Remotion
 * can render any frame range in any order (scripts/render-batches.js).
 *
 * The sounds themselves are generated by scripts/generate-audio.js, which ports
 * the reference HTML's WebAudio synth to WAV files in public/sounds/.
 */
import settings from '../settings.json';
import manifest from './sound-manifest.json';
import { BONUS_CLOCK_START, FPS, QUESTIONS, TIMELINE, TOTAL, buildQuestionPlan } from './timing';

export type Sfx = Exclude<keyof typeof manifest, `music-${string}`>;

export type Cue = {
  /** absolute frame the clip starts on */
  frame: number;
  sfx: Sfx;
  /** pitch via playback rate (the HTML pitched tones by frequency) */
  rate?: number;
  volume?: number;
};

export const SOUND_ENABLED = Boolean((settings as { sound?: { enabled?: boolean } }).sound?.enabled);

/** Music loop = exactly 256 frames at 30fps; see scripts/generate-audio.js */
export const MUSIC_LOOP_FRAMES = 256;

/** Clip length in frames (rounded up, +1 so a clip is never cut). */
export const clipFrames = (sfx: Sfx, rate = 1) => Math.ceil((manifest[sfx] * FPS) / rate) + 1;

const levelIndexOf = (level: string) => Math.max(0, settings.levels.findIndex((l) => l.name === level));

const HOOK_A = settings.timing.hookA;
const RANK_COUNT = (settings.scoreboard.ranks as string[][]).length;

/** Scoreboard beats — keep in sync with Scoreboard.tsx (rowBase 46, step 22). */
const SB_ROW_BASE = 46;
const SB_STEP = 22;

/** Music intensity for question n: the HTML's [0,1,1,2,2] ramp, spread over however many questions there are. */
const intensityForQuestion = (n: number) => [0, 1, 1, 2, 2][Math.min(4, Math.floor((n * 5) / Math.max(1, TOTAL)))];

const buildCues = (): Cue[] => {
  const cues: Cue[] = [];
  const add = (frame: number, sfx: Sfx, extra: Partial<Cue> = {}) =>
    cues.push({ frame: Math.round(frame), sfx, ...extra });

  const ticks = (clockStart: number, seconds: number, low: 'thump' | 'tick-low') => {
    // The HTML ticks on every whole-second change, from T-1 down to 1.
    for (let k = 1; k < seconds; k++) {
      const left = seconds - k;
      add(clockStart + k * FPS, left <= 3 ? low : 'tick');
    }
  };

  TIMELINE.segments.forEach((seg) => {
    const f0 = seg.from;
    switch (seg.kind) {
      case 'hook': {
        // Scene A: heartbeat, three hard-pair blips, two boom hits on the headline slams
        add(f0 + 1, 'thump');
        [0, 36, 72].forEach((at, i) => add(f0 + at, 'blip', { rate: (500 + i * 160) / 500 }));
        add(f0 + 26, 'boom');
        add(f0 + 48, 'boom');
        // Scene B: rules
        add(f0 + HOOK_A + 4, 'thump');
        add(f0 + HOOK_A + 4, 'rule-sweep');
        add(f0 + HOOK_A + 38, 'ping-hi');
        add(f0 + HOOK_A + 84, 'jingle-rules');
        break;
      }
      case 'levelCard': {
        add(f0 + 3, 'thump');
        add(f0 + 15, 'boom');
        break;
      }
      case 'question': {
        const q = QUESTIONS[seg.index];
        const plan = buildQuestionPlan(q, levelIndexOf(q.level), seg.index === 0);
        if (seg.index === 0) add(f0, 'title');

        // emoji pair pops in (the "+" is silent, like the HTML)
        add(f0 + plan.emojiStart, 'pop');
        add(f0 + plan.emojiStart + 16, 'pop');

        // clock: tick each second, chime on both free letters (2/3 and 1/3 of the clock)
        ticks(f0 + plan.timerStart, plan.timerSeconds, 'tick-low');
        add(f0 + plan.timerStart + plan.timerFrames * (1 / 3), 'flip');
        add(f0 + plan.timerStart + plan.timerFrames * (2 / 3), 'flip');

        // clock ends: bulbs flare, then every letter flips with a rising tone
        add(f0 + plan.flips, 'flare');
        add(f0 + plan.flips + 5, 'flare');
        Array.from(q.word).forEach((_, k) =>
          add(f0 + plan.flips + k * 1.4, 'letter', { rate: (520 + k * 60) / 520 }),
        );

        // emojis merge into the answer card
        add(f0 + plan.stamp - 16, 'whoosh');
        add(f0 + plan.stamp + 6, 'stamp');
        add(f0 + plan.stamp + 10, 'chime-arp');
        break;
      }
      case 'bonus': {
        const clockStart = f0 + BONUS_CLOCK_START();
        const clockFrames = Math.round(seg.puzzle.seconds * FPS);
        const clockEnd = clockStart + clockFrames;
        add(f0, 'siren');
        add(f0, 'whoosh');
        add(f0 + settings.bonus.preRollFrames + 2, 'pop');
        // last 3 seconds are a heartbeat, the rest are ticks; a 2s drumroll rides the end
        ticks(clockStart, seg.puzzle.seconds, 'thump');
        if (seg.puzzle.seconds > 3) add(clockEnd - 2 * FPS, 'drumroll');
        add(clockEnd, 'stamp');
        add(clockEnd + settings.bonus.answerChipDelayFrames, 'chime-erase');
        break;
      }
      case 'scoreboard': {
        for (let i = 0; i < RANK_COUNT; i++) {
          const fromBottom = RANK_COUNT - 1 - i;
          add(f0 + SB_ROW_BASE + fromBottom * SB_STEP, 'row', {
            rate: (330 + (RANK_COUNT - 1 - i) * 110) / 330,
          });
        }
        add(f0 + SB_ROW_BASE + (RANK_COUNT - 1) * SB_STEP + 21, 'legend');
        break;
      }
      case 'endScreen': {
        add(f0 + 9, 'boom');
        add(f0 + 52, 'jingle-cta');
        add(f0 + 140, 'ding');
        add(f0 + 196, 'ding-hi');
        break;
      }
    }
  });

  return cues.sort((a, b) => a.frame - b.frame);
};

export const CUES: Cue[] = buildCues();

/* ------------------------------------------------------------------ music */

/** First frame with no music (the HTML stops the score when the scoreboard starts). */
export const MUSIC_END = (TIMELINE.segments.find((s) => s.kind === 'scoreboard') ?? { from: TIMELINE.totalFrames }).from;

/** Frames at which the music intensity (0/1/2) changes. Intensity holds until the next entry. */
const intensityChanges = (): { frame: number; level: number }[] => {
  const out: { frame: number; level: number }[] = [{ frame: 0, level: 0 }];
  let qn = 0;
  TIMELINE.segments.forEach((seg) => {
    if (seg.kind === 'question') {
      out.push({ frame: seg.from, level: intensityForQuestion(qn) });
      qn++;
    } else if (seg.kind === 'bonus') {
      out.push({ frame: seg.from, level: 2 });
    }
  });
  return out;
};

const RAMP = 10; // frames for a layer to fade in/out
const DUCK_FLOOR = 0.44; // HTML: music bus .5 -> .22 while any sound plays

/**
 * Per-frame music volume for one layer (0 = base, 1, 2), with the HTML's
 * "duck under every sound" behaviour baked in. Precomputed once.
 */
const buildMusicEnvelopes = (): Float32Array[] => {
  const n = Math.max(1, TIMELINE.totalFrames);
  const changes = intensityChanges();

  // layer on/off target per frame, then a linear ramp towards it
  const duck = new Float32Array(n).fill(1);
  const duckFrames = FPS * 0.28;
  const recover = FPS * 0.18;
  for (const c of CUES) {
    for (let f = Math.max(0, c.frame); f < Math.min(n, c.frame + duckFrames + recover * 4); f++) {
      const dt = f - c.frame;
      const v = dt < duckFrames ? DUCK_FLOOR : 1 - (1 - DUCK_FLOOR) * Math.exp(-(dt - duckFrames) / recover);
      if (v < duck[f]) duck[f] = v;
    }
  }

  return [0, 1, 2].map((layer) => {
    const env = new Float32Array(n);
    let level = 0;
    let ci = 0;
    let cur = layer === 0 ? 1 : 0;
    for (let f = 0; f < n; f++) {
      while (ci < changes.length && changes[ci].frame <= f) level = changes[ci++].level;
      const target = f >= MUSIC_END ? 0 : layer <= level ? 1 : 0;
      const step = 1 / RAMP;
      cur = cur < target ? Math.min(target, cur + step) : Math.max(target, cur - step);
      env[f] = cur * duck[f];
    }
    return env;
  });
};

export const MUSIC_ENVELOPES = buildMusicEnvelopes();

/** Does `layer` make any sound inside [from, to)? Lets the soundtrack skip silent loop repeats. */
export const layerAudible = (layer: number, from: number, to: number) => {
  const env = MUSIC_ENVELOPES[layer];
  for (let f = Math.max(0, from); f < Math.min(env.length, to); f += 3) if (env[f] > 0.001) return true;
  return false;
};
